According to \eqref{eq:weak-part} it suffices to show that for any partition $\mathcal{P}$ of the vertices of $H$, $\sum_{e\in E(H)}(\mathcal{P}(e)-1)\ge k(|\mathcal{P}|-1)$.
To see this, assume that $\mathcal{P}=\{V_1,\ldots,V_s\}$. Then $\sum_{i=1}^s |V_i|=t$, and for each $e\in E(H)$, $|e|=\sum_{i=1}^s |e\cap V_i|$. By the last equality, it is not hard to check that
\begin{equation*}
    |e|=\mathcal{P}(e)+\sum_{i=1}^s \max\{0,|e\cap V_i|-1\}.
\end{equation*}
It follows that
\begin{equation*}
\begin{aligned}
    \sum_{e\in E(H)} (\mathcal{P}(e)-1)=&\sum_{e\in E(H)} \Big(|e|-\sum_{i=1}^s \max\{0,|e\cap V_i|-1\}-1\Big)\\
    &= \sum_{e\in E(H)} (|e|-1)-\sum_{i=1}^s\sum_{e\in E(H)} \max\{0,|e\cap V_i|-1\}\\
    &\ge k(t-1)-\sum_{i=1}^s k(|V_i|-1)=k(s-1),
\end{aligned}
\end{equation*}
where the last inequality follows from \eqref{eq:weak-part-2}.

Assume Conjecture~\ref{conj:weak} is true.
Let $I_1,\dots,I_t\subseteq[n]$ be subsets satisfying the conditions of Conjecture~\ref{conjecture}.
For all $i\in [n]$, let $e_i=\{j\in [t]: i\in I_j\}$.
Let $H$ be a (multi)hypergraph with vertex set $[t]$ and edge set $E(H)=\{e_i:i\in[n]\}$.

\begin{claim} For all subsets $J\subseteq[t]$, we have $\sum_{e\in E(H)}^{} \max(0,|e\cap J|-1)={\rm wt}(I_j:j\in J)$.
\end{claim}

\begin{proof}
  We have
  \begin{equation*}
      \begin{aligned}
          \sum_{i\in [n]} \max\{0,|e_i\cap J|-1\}=\sum_{i\in [n]} |e_i\cap J|-\abs{\bigcup_{j\in J} I_j}=\sum_{j\in J} |I_j|-\abs{\bigcup_{j\in J} I_j}={\rm wt}(I_J),
      \end{aligned}
  \end{equation*}
  where the first equality follows from the fact $\cup_{j\in J} I_j=\{i\in [n]: |e_i\cap J|\ge 1\}$, the second equality follows from easy double-counting, and the last equality follows from \eqref{definition-weight}.
\end{proof}

The following is an easy consequence of Lemmas~\ref{lem:rand-2} and Claim~\ref{lem:new-1}.

\begin{claim} $H$ is $k$-weakly-partitioned-connected.
\end{claim}
\begin{proof}
  By Claim~\ref{lem:new-1} and the setup of Conjecture~\ref{conjecture}, it is clear that for each $J\subsetneq [t]$
\begin{align}
  \sum_{e\in E(H)}^{} \max\{0,|e\cap J|-1\}  \ = \  {\rm wt}(I_J) \  &\le \   k(|J|-1) \nonumber\\
  \text{~and~} \sum_{e\in E(H)}^{} \max\{0,|e|-1\} \ = \ {\rm wt}(I_{[t]}) \ &\ge \   k(t-1).
\end{align}
It follows by Lemma~\ref{lem:rand-2} that $H$ is $k$-weakly-partition-connected.
\end{proof}



By our assumption that Conjecture~\ref{conj:weak} is true, there exists a tree-assignment $G$ of $H$ that is $k$-distinguishable. Note that by definition $G$ has $k(t-1)$ edges, which are labeled by the hyperedges of $H$. Let $S\subseteq [n]$ be the subset so that $\{e_s:s\in S\}$ forms the set of those labels. Then, an edge $\{j,j'\}$ of $G$ has label $e_s$ for some $s\in S$ if and only if $s\in I_j\cap I_{j'}$.

Recall that
\begin{align}
  M_{k,(I_1,\dots,I_t)} =
  \left(
  \begin{array}{c}
    \mathcal{B}_t\otimes \mathcal{I}_k  \\\hline
  {\rm diag}\Big(V_k(I_j\cap I_{j'}): \{j,j'\}\in \binom{[t]}{2}\Big) \\
  \end{array}
\right), \end{align}
and that the $\binom{t}{2}k$ columns are labeled by the pairs $\{j,j'\}\in\binom{[t]}{2}$, according to the $\binom{t}{2}$ Vandermonde matrices in the bottom diagonal.
Our goal is to show that $M_{k,(I_1,\dots,I_t)}$ is nonsingular. As in the proof of Theorem~\ref{theorem-weaker}, it suffices to show the nonsingularity of

\begin{align}
M'_{k,(I_1,\ldots,I_t)}
\coloneqq
\left(
  \begin{array}{c}
  \mathcal{I}_k\otimes \mathcal{B}_t  \\\hline
  \big(\mathcal{C}_i:0\le i\le k-1\big) \\
  \end{array}
\right),
\end{align}
where $\mathcal{C}_i={\rm diag}\Big(V_k^{(i)}(I_j\cap I_{j'}): \{j,j'\}\in \binom{[t]}{2}\Big)$ and $V_k^{(i)}(I_j\cap I_{j'})$ is the $(i+1)$-th column of $V_k(I_j\cap I_{j'})$. Note that $M'_{k,(I_1,\ldots,I_t)}$ is obtained by permuting the columns of $M_{k,(I_1,\ldots,I_t)}$, with the column labels remaining unchanged.

The following fact is easy to verify by definition.

\begin{fact} Each row of $\big(\mathcal{C}_i:0\le i\le k-1\big)$ has exactly $k$ nonzero entries, which has the form $x_s^0, x_s^1,\dots,x_s^{k-1}$ for some $s\in S$. Moreover, there is $\{j,j'\}\in\binom{[t]}{2}$ so that $s\in I_j\cap I_{j'}$, and those $k$ nonzero entries are all contained in $\{j,j'\}$-labeled columns.
\end{fact}

Let us consider $\binom{t}{2}k\times \binom{t}{2}k$ submatrix $M'$ of $M'_{k,(I_1,\dots,I_t)}$ obtained as follows:

\begin{enumerate}
\item Keep the top $\binom{t-1}{2}k\times \binom{t}{2}k$ submatrix $\mathcal{I}_k\otimes B_t$.
\item For every edge $\{j,j'\}$ in $G$ of label $e_s$, keep the row in $\big(\mathcal{C}_i:0\le i\le k-1\big)$ with nonzero entries $x_s^0,\dots,x_s^{k-1}$ in $\{j,j'\}$-labeled columns (this is well-defined according to Fact~\ref{fact:M'-1}).
\item Remove all other rows.
\end{enumerate}

\noindent As $G$ has $k(t-1)$ edges, precisely $k(t-1)$ rows are kept in step $2$. Therefore, $M'$ has $\binom{t-1}{2}k + k(t-1) = \binom{t}{2}k$ rows and is thus square.

Below we show that $M'$ has a nonzero determinant, thereby implying that $M'_{k,(I_1,\ldots,I_t)}$ and hence $M_{k,(I_1,\ldots,I_t)}$ are nonsingular, which is the claim of Conjecture~\ref{conjecture}, and thus establishing Theorem~\ref{thm:complete-2}. For that purpose, it is enough to show that there is a monomial that appears as a nonvanishing term in the determinant expansion of $M'$. To find such a monomial, we use the fact that $G$ is $k$-distinguishable.

Recall that for a subgraph $F$ of $G$, we use $v^F\in\mathbb{N}^S$ to denote the vector that counts the  edge labels in $F$, where for $s\in S$, $v_s^F$ is the number of edges with label $e_s$. Note that $v^F$ is a vector of length $|S|$ whose coordinates are indexed by elements in $S$. For spanning trees $T,T_0,\ldots,T_{k-1}$ of $G$, define

\begin{align}
x^T := \prod_{s\in S}^{} x_s^{v^T_s}\text{\qquad and\qquad }x^{(T_0,\dots,T_{k-1})}:=\prod_{i=0}^{k-1} (x^{T_i})^i. \end{align}

\noindent Observe that, by the definition in \eqref{eq:signature}, we have $v^{(T_0,\ldots,T_{k-1})}_s=\sum_{i=0}^{k-1} i\cdot v_s^{T_i}$ for all $s\in S$. Hence, it follows from \eqref{eq:complete-1} that
\begin{align} x^{(T_0,\dots,T_{k-1})}=  \prod_{s\in S}^{} x_s^{v^{(T_0,\dots,T_{k-1})}_s}.
\end{align}


Since $G$ is $k$-distinguishable, there exists a tree decomposition $T_0,\dots,T_{k-1}$ such that for any other tree-assignment $T_0',\dots,T_{k-1}'$, we have that the signatures $v^{(T_0,\dots,T_{k-1})}\neq v^{(T_0',\dots,T_{k-1}')}$.
Thus, it follows by \eqref{equ:new-1} that the monomials $x^{(T_0,\dots,T_{k-1})}\neq x^{(T_0',\dots,T_{k-1}')}$.

\begin{claim} Let $T_0,\ldots,T_{k-1}$ be spanning trees as defined above. Then, $x^{(T_0,\dots,T_{k-1})}$ appears as a nonvanishing term in the determinant expansion of $M'$.
\end{claim}

